// Bitmap fonts and images generated by tools/fontgen.py.
#pragma once
#include <stdint.h>

namespace stoprock {

struct Glyph {
    uint16_t code;   // Unicode code point
    int8_t dx, dy;   // offset of the ink box from the text origin
    uint8_t w, h;    // ink box size
    uint8_t adv;     // pen advance
    uint16_t off;    // offset into the font's bitmap data
};

struct Font {
    const Glyph* glyphs;
    const uint8_t* bits;  // per glyph: h rows of (w + 7) / 8 bytes, MSB = leftmost
    uint16_t count;
};

struct Bitmap {
    const uint8_t* bits;  // rows of (w + 7) / 8 bytes, MSB = leftmost, 1 = black
    uint16_t w, h;
};

// A shape positioned by its centre (cx, cy) inside the bitmap.
struct Sprite {
    Bitmap bm;
    uint8_t cx, cy;
};

extern const Font kFontDseg37;      // newest result, at the top
extern const Font kFontDseg33;      // ... an H2H of 20.00s, too wide at 37
extern const Font kFontDseg24;      // coach page 2's newest result
extern const Font kFontDseg16;      // percentage
extern const Font kFontSpleen6x12;  // labels and tips
extern const Font kFontSpleen12x24; // the hold hints (only their letters)
extern const Font kFontSpleen16x32; // large THEM heading (only its letters)
extern const Font kFontMenuTitle;  // Nunito ExtraBold, 18 px
extern const Font kFontMenuDetail; // Nunito Bold, 13 px
extern const Bitmap kLogo;         // 176 px wordmark
extern const Bitmap kOffPage;       // 200 x 200 wake screen
extern const Bitmap kBasicIntro;    // 200 x 200 tutorial pointing at the timing buttons
extern const Bitmap kPositionCard;  // position tip frame, arrow and instructions
extern const Bitmap kPositionTitles[];
extern const Bitmap kLogoStrip;     // 106 x 22 wordmark for competition's badge strip
extern const Sprite kRockSmall;     // a rock slot (radius 5)
extern const Sprite kCursorSmall;   // cursor: the slot drawn bold
extern const Sprite kMadeSmall;     // made: the rock filled
extern const Sprite kMissedSmall;   // missed: a dot in the ring
extern const Sprite kStopwatch;      // where a time is awaited, in the large row (ring radius 10)
extern const Sprite kStopwatchSmall; // ... and in coach page 2's smaller row (radius 6)

// Slash of the drawn % sign, for each digit height; sprite origin = top-left of the sign.
struct PercentSlash {
    uint8_t digitHeight;
    const Sprite* sprite;
};
extern const PercentSlash kPercentSlashes[];
extern const uint8_t kPercentSlashCount;

}  // namespace stoprock
